// Inputs expected:
// $json.full_agenda_text  → string
// $json.case_items        → array of { item_number, raw_text, attachments? }
// $json.attachment_data   → array of { item_number, title, page, link, text }

const fullAgendaText = $json.full_agenda_text || "";
const caseItems = Array.isArray($json.case_items) ? $json.case_items : [];
const attachmentData = Array.isArray($json.attachment_data) ? $json.attachment_data : [];

// Helper: sort by numeric item_number
function sortByItemNumber(a, b) {
  return parseInt(a.item_number, 10) - parseInt(b.item_number, 10);
}

const enrichedCaseItems = caseItems.map(item => {
  const base = {
    item_number: item.item_number,
    raw_text: item.raw_text || null
  };

  // Handle attachments only if they exist
  if (Array.isArray(item.attachments) && item.attachments.length > 0) {
    const enrichedAttachments = item.attachments.map(att => {
      // Find matching entry in attachmentData
      const match = attachmentData.find(a =>
        a.item_number === item.item_number &&
        a.title === att.title
      );

      return {
        title: att.title || null,
        page: att.page || null,
        link: att.link || null,
        text: match ? (match.text || null) : null
      };
    });

    if (enrichedAttachments.length > 0) {
      base.attachments = enrichedAttachments;
    }
  }

  return base;
}).sort(sortByItemNumber);

return [
  {
    json: {
      full_agenda_text: fullAgendaText,
      case_items: enrichedCaseItems
    }
  }
];
